import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Brand, ClimbingArt, Icon } from './components/Icon';
import { defaultProfile, emptyState, focusLabels, hasPainSignal, makeProvider, sessionId } from './lib/provider';
import { knowledgeMetadata, knowledgeQuestions } from './lib/knowledge';
import type { Answer, AppState, Citation, Dimension, FeedbackInput, Focus, Page, Plan, ProfileInput, Provider, ProviderMode, Report } from './lib/types';

const navigation: { page: Page; label: string; icon: string; group?: string }[] = [
  { page: 'today', label: '今日训练', icon: 'today' }, { page: 'profile', label: '能力画像', icon: 'profile' },
  { page: 'plan', label: 'AI 周计划', icon: 'plan' }, { page: 'training', label: '训练记录', icon: 'training' },
  { page: 'report', label: '反馈报告', icon: 'report' }, { page: 'knowledge', label: '知识助手', icon: 'knowledge' },
  { page: 'account', label: '个人与历史', icon: 'account' },
];
const pageMeta: Record<Page, { title: string; eyebrow: string; subtitle: string }> = {
  today: { title: '今天，向上一步。', eyebrow: 'YOUR NEXT MOVE', subtitle: '让每一次攀爬，都有清晰的下一步。' },
  onboarding: { title: '先认识一下你。', eyebrow: 'GET TO KNOW YOU', subtitle: '用几分钟建立档案，把计划放进你的真实生活。' },
  profile: { title: '你的能力画像', eyebrow: 'KNOW YOUR CLIMB', subtitle: '分清已知事实与待验证的判断，每一条观察都有依据。' },
  plan: { title: '一周，稳稳向上。', eyebrow: 'A PLAN THAT FITS', subtitle: '适配你的目标、场地和可用时间。确认之后再开始。' },
  training: { title: '专注这一次攀爬。', eyebrow: 'ONE MOVE AT A TIME', subtitle: '按自己的节奏执行。结束训练与提交反馈分别保存。' },
  report: { title: '每次反馈，都有回声。', eyebrow: 'LEARN FROM EACH SESSION', subtitle: '把一次真实经历，转成下一次可执行的安排。' },
  knowledge: { title: '带着问题，继续攀爬。', eyebrow: 'A LITTLE CLARITY', subtitle: '围绕当前训练提问。依据不足时，明确告诉你。' },
  account: { title: '你的攀爬足迹', eyebrow: 'YOUR CLIMBING JOURNEY', subtitle: '训练事实、计划变化和画像版本，都留在这里。' },
};
function currentPage(): Page { const p = location.hash.slice(1); return p in pageMeta ? p as Page : 'today'; }
function fmtDate(value?: string) { if (!value) return '刚刚'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Shanghai' }); }
function engineLabel(state: AppState, mode: ProviderMode) { if (mode === 'demo') return '演示模式 · 示例规则，未调用模型'; return /llm|openai/i.test(state.engine) ? 'API 模式 · 已连接模型服务' : 'API 模式 · 示例规则，未调用模型'; }
function Pill({ children, tone = 'green' }: { children: ReactNode; tone?: string }) { return <span className={`pill pill-${tone}`}>{children}</span>; }
function Empty({ title, text, action, onClick, icon = 'mountain' }: { title: string; text: string; action?: string; onClick?: () => void; icon?: string }) { return <div className="empty-state"><span className="empty-icon"><Icon name={icon} size={30}/></span><h2>{title}</h2><p>{text}</p>{action && <button className="button primary" onClick={onClick}>{action}<Icon name="arrow" size={17}/></button>}</div>; }
function Sources({ citations }: { citations?: Citation[] }) { if (!citations?.length) return null; return <div className="source-list">{citations.map((c, i) => <div className="source" key={c.id || i}><Icon name="knowledge" size={16}/><div>{c.url ? <a href={c.url} target="_blank" rel="noreferrer">[{c.id}] {c.title}<Icon name="link" size={12}/></a> : <strong>[{c.id}] {c.title}</strong>}<small>{c.source_type || '知识来源'}{c.source_title ? ` · ${c.source_title}` : ''}</small><p>{c.summary}</p>{c.support_note && <p>支持范围：{c.support_note}</p>}{c.applicability && <p>适用范围：{c.applicability}</p>}{c.last_verified && <small>来源核验：{c.last_verified}</small>}{c.review_status && <small>{c.review_status}</small>}</div></div>)}</div>; }
function Modal({ title, children, close }: { title: string; children: ReactNode; close: () => void }) { useEffect(() => { const handler = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); }; document.addEventListener('keydown', handler); const original = document.body.style.overflow; document.body.style.overflow = 'hidden'; return () => { document.removeEventListener('keydown', handler); document.body.style.overflow = original; }; }, [close]); return <div className="modal-backdrop" onClick={close}><section className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e => e.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button className="icon-button" aria-label="关闭" onClick={close}><Icon name="close"/></button></div>{children}</section></div>; }

type Act = (operation: () => Promise<AppState>, message?: string, after?: () => void) => Promise<boolean>;
type Shared = { state: AppState; provider: Provider; act: Act; go: (p: Page) => void; busy: string; mode: ProviderMode; toast: (m: string, error?: boolean) => void };

export default function App() {
  const [page, setPage] = useState<Page>(currentPage);
  const [state, setState] = useState<AppState>(emptyState());
  const [mode, setMode] = useState<ProviderMode>(() => localStorage.getItem('climbai.mode') === 'api' ? 'api' : 'demo');
  const [apiUrl, setApiUrl] = useState(() => localStorage.getItem('climbai.apiUrl') || 'http://127.0.0.1:8000');
  const [busy, setBusy] = useState(''); const [ready, setReady] = useState(false);
  const [message, setMessage] = useState<{ text: string; error: boolean } | null>(null);
  const [settings, setSettings] = useState(false); const [about, setAbout] = useState(false); const [confirmSample, setConfirmSample] = useState(false);
  const provider = useMemo(() => makeProvider(mode, apiUrl), [mode, apiUrl]);
  const toast = (text: string, error = false) => setMessage({ text, error });
  useEffect(() => { let cancelled = false; setReady(false); provider.getState().then(s => { if (!cancelled) { setState(s); setReady(true); } }).catch(e => { if (!cancelled) { toast(e.message, true); setReady(true); } }); return () => { cancelled = true; }; }, [provider]);
  useEffect(() => { const f = () => setPage(currentPage()); window.addEventListener('hashchange', f); return () => window.removeEventListener('hashchange', f); }, []);
  useEffect(() => { if (!message) return; const timer = setTimeout(() => setMessage(null), message.error ? 9000 : 4500); return () => clearTimeout(timer); }, [message]);
  const go = (p: Page) => { setPage(p); location.hash = p; window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const act: Act = async (operation, success, after) => {
    if (busy) return false; setBusy(mode === 'demo' ? '正在整理你的训练安排…' : 'Coach 正在处理，请稍候…');
    try { setState(await operation()); if (success) toast(success); after?.(); return true; } catch (e) { toast(e instanceof Error ? e.message : '操作失败，请重试。', true); return false; } finally { setBusy(''); }
  };
  const sample = () => { if (mode !== 'demo') { toast('请先切回演示模式，API 模式不会写入模拟样例。'); return; } if (state.profile) setConfirmSample(true); else void loadSample(); };
  const loadSample = async () => { setConfirmSample(false); await act(() => provider.loadDemo(), '已加载模拟案例。所有记录为示例数据。', () => go('today')); };
  const pending = state.reports.filter(r => r.adjustment.status === 'pending').length;
  const shared: Shared = { state, provider, act, go, busy, mode, toast };
  const meta = pageMeta[page];
  return <div className="app-shell">
    <aside className="sidebar"><button className="brand-button" aria-label="回到今日训练" onClick={() => go('today')}><Brand/></button><div className="nav-eyebrow">训练空间</div><nav aria-label="主导航">{navigation.map(n => <button className={`nav-item ${page === n.page ? 'active' : ''}`} data-testid={`nav-${n.page}`} aria-current={page === n.page ? 'page' : undefined} key={n.page} onClick={() => go(n.page)}><Icon name={n.icon}/><span>{n.label}</span>{n.page === 'report' && pending > 0 && <span className="nav-count">{pending}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="coach-note"><Icon name="leaf" size={20}/><p>不必每次都挑战极限。<br/><strong>稳定的节奏，也在向上。</strong></p></div><button className="sidebar-person" onClick={() => go('account')}><span className="avatar">{state.profile?.nickname.slice(0, 1) || '你'}</span><span><strong>{state.profile?.nickname || '欢迎来到 ClimbAI'}</strong><small>{state.profile ? '查看我的攀爬足迹' : '从你的第一个目标开始'}</small></span><Icon name="chevron" size={16}/></button></div></aside>
    <div className="workspace"><header className="topbar"><span className="breadcrumbs">我的训练空间 <span>/</span> {meta.title.replace(/[。？]/g, '')}</span><div className="top-actions"><button className="mode-indicator" onClick={() => setSettings(true)}><span className="status-dot"/>{mode === 'demo' ? '演示模式' : 'API 模式'}<Icon name="settings" size={14}/></button><button className="text-button about-button" onClick={() => setAbout(true)}>项目说明<Icon name="link" size={13}/></button></div></header>
      <main id="main-content"><div className="page-heading"><div><div className="eyebrow">{meta.eyebrow}</div><h1>{page === 'today' && state.profile ? `${state.profile.nickname}，今天向上一步。` : meta.title}</h1><p>{meta.subtitle}</p></div>{page !== 'onboarding' && <button className="button subtle heading-action" onClick={() => go('onboarding')}><Icon name="edit" size={16}/>{state.profile ? '调整目标' : '建立档案'}</button>}</div>
      <div className="mode-banner"><Icon name="spark" size={15}/><span>{engineLabel(state, mode)}</span>{mode === 'demo' && <button onClick={sample}>体验模拟案例<Icon name="arrow" size={13}/></button>}</div>
      {state.paused && <div className="pause-banner" role="alert"><Icon name="alert"/><div><strong>相关攀爬任务已暂停</strong><p>你记录了不适。先停止引发不适的活动，并寻求专业建议；系统不提供诊断或康复处方。</p></div><button className="text-button" onClick={() => go('onboarding')}>查看状态</button></div>}
      {!ready ? <div className="empty-state"><span className="spinner"/><p>正在读取你的训练空间…</p></div> : <>
        {page === 'today' && <Dashboard {...shared} sample={sample}/>}
        {page === 'onboarding' && <Onboarding {...shared}/>}
        {page === 'profile' && <ProfilePage {...shared}/>}
        {page === 'plan' && <PlanPage {...shared}/>}
        {page === 'training' && <TrainingPage {...shared}/>}
        {page === 'report' && <ReportPage {...shared}/>}
        {page === 'knowledge' && <KnowledgePage {...shared} setState={setState}/>}
        {page === 'account' && <AccountPage {...shared}/>}
      </>}
      <footer className="app-footer"><span><Brand compact/> <span>ClimbAI · One move at a time.</span></span><button onClick={() => setAbout(true)}>作品集 Demo · 数据与建议说明</button></footer>
      </main>
    </div>
    <nav className="mobile-nav" aria-label="移动端主导航">{navigation.filter(n => ['today', 'plan', 'training', 'knowledge', 'account'].includes(n.page)).map(n => <button key={n.page} className={page === n.page || (n.page === 'account' && page === 'profile') || (n.page === 'training' && page === 'report') ? 'active' : ''} onClick={() => go(n.page)}><Icon name={n.icon}/><span>{n.page === 'account' ? '我的' : n.page === 'knowledge' ? '知识' : n.page === 'training' ? '训练' : n.page === 'plan' ? '计划' : '今日'}</span></button>)}</nav>
    {busy && <div className="busy-indicator" role="status"><span className="spinner"/>{busy}</div>}
    {message && <div className={`toast ${message.error ? 'error' : ''}`} role={message.error ? 'alert' : 'status'}><Icon name={message.error ? 'alert' : 'check'} size={18}/><span>{message.text}</span><button aria-label="关闭提示" onClick={() => setMessage(null)}><Icon name="close" size={16}/></button></div>}
    {settings && <ConnectionModal mode={mode} apiUrl={apiUrl} configurationWarning={state.configuration_warning} close={() => setSettings(false)} apply={async (newMode, url) => { if (busy) return; setBusy('正在检查连接…'); try { const next = await makeProvider(newMode, url).getState(); localStorage.setItem('climbai.mode', newMode); localStorage.setItem('climbai.apiUrl', url); setMode(newMode); setApiUrl(url); setState(next); setSettings(false); toast(newMode === 'demo' ? '已切回本地演示空间。' : '后端连接成功。请查看页面上的实际运行模式。'); } catch (e) { toast(e instanceof Error ? e.message : '连接失败', true); } finally { setBusy(''); } }}/>}
    {about && <Modal title="关于 ClimbAI" close={() => setAbout(false)}><div className="about-content"><Brand/><p className="large-text">让每一次攀爬，都有清晰的下一步。</p><p>一个面向室内抱石爱好者的 AI Coach Agent 产品作品集：建立画像、制定计划、检索知识，并从训练反馈中持续调整。</p><div className="notice"><strong>当前体验如何工作</strong><p>演示模式使用可复现的示例规则，不调用大模型。API 模式连接独立后端，页面会标记实际提供建议的引擎。模拟案例、示例知识与训练模板不代表真实用户效果。</p></div><p>训练内容为产品演示条目，上线前需要攀岩专业人员审阅。它不替代现场指导，也不提供医学诊断或康复处方。</p><div className="mini-flow"><span>理解你</span><Icon name="arrow" size={15}/><span>查依据</span><Icon name="arrow" size={15}/><span>做计划</span><Icon name="arrow" size={15}/><span>听反馈</span></div></div></Modal>}
    {confirmSample && <Modal title="加载模拟案例" close={() => setConfirmSample(false)}><p className="modal-copy">这会替换当前浏览器中的演示档案、训练记录和计划。需要保留时，请先在个人中心导出数据。</p><div className="modal-actions"><button className="button subtle" onClick={() => setConfirmSample(false)}>保留当前记录</button><button className="button primary" onClick={loadSample}>替换为模拟案例</button></div></Modal>}
  </div>;
}

function Dashboard({ state, go, sample, busy }: Shared & { sample: () => void }) {
  const plan = state.current_plan; const next = plan?.sessions.find(s => !state.logs.some(l => l.session_id === s.id)) || plan?.sessions[0];
  const pending = state.reports.find(r => r.adjustment.status === 'pending');
  return <div className="dashboard"><section className="hero"><div className="hero-copy"><div className="hero-kicker"><span className="tiny-line"/> YOUR CLIMB, YOUR PACE</div><h2>{state.profile ? <>为下一次到馆，<br/>留一个清晰重点。</> : <>攀爬有方向，<br/>进步有迹可循。</>}</h2><p>{state.profile ? plan?.summary || '档案已就绪。让目标、时间和当前状态一起决定训练安排。' : '认识自己的训练重点，获得适合你的安排。把每一次训练反馈，变成下一次行动。'}</p><div className="hero-actions"><button className="button lime" disabled={!!busy || state.paused} onClick={() => go(state.profile ? plan ? 'plan' : 'onboarding' : 'onboarding')}>{state.profile ? plan ? '查看我的训练计划' : '生成我的计划' : '建立我的训练计划'}<Icon name="arrow" size={18}/></button>{!state.profile && <button className="hero-text-button" onClick={sample}>先看模拟案例<Icon name="chevron" size={14}/></button>}</div><div className="hero-caption"><Icon name="shield" size={15}/>{state.profile ? '依据可追溯 · 计划由你确认' : '3 分钟建档目标 · 体验目标，待测试验证'}</div></div><div className="hero-visual"><ClimbingArt/><div className="art-label"><span className="status-dot"/> 向上，不止一种节奏</div></div></section>
    {state.profile ? <><div className="metric-grid"><div className="metric-card"><span>本周计划</span><strong>{plan?.sessions.length || 0}<small>次到馆</small></strong><Icon name="plan"/></div><div className="metric-card"><span>已记录训练</span><strong>{state.logs.length}<small>次</small></strong><Icon name="training"/></div><div className="metric-card"><span>已提交反馈</span><strong>{state.reports.length}<small>次</small></strong><Icon name="message"/></div></div>
    <div className="dashboard-grid"><section className="card next-session"><div className="section-head"><h2><Icon name="training"/>下一次训练</h2><Pill tone={state.paused ? 'orange' : 'green'}>{state.paused ? '已暂停' : plan?.status === 'confirmed' ? '计划已确认' : '等待确认'}</Pill></div>{next ? <><div className="session-overline">{next.day} <span>·</span> <Icon name="clock" size={14}/>{next.duration_minutes} 分钟</div><h3>{next.title}</h3><p className="muted">{next.rationale}</p><div className="exercise-preview">{next.exercises.slice(0, 3).map((e, i) => <div key={e.id}><span>{String(i + 1).padStart(2, '0')}</span><strong>{e.title}</strong><small>{e.duration_minutes} min</small></div>)}</div><button className="button primary full" disabled={state.paused || !!busy} onClick={() => go(plan?.status === 'confirmed' ? 'training' : 'plan')}>{plan?.status === 'confirmed' ? '查看并开始训练' : '先确认计划'}<Icon name="arrow" size={17}/></button></> : <Empty title="还没有训练安排" text="生成计划后，这里会告诉你下一次练什么。" action="设置目标与时间" onClick={() => go('onboarding')}/>}</section>
    <section className="card insight-card"><div className="section-head"><h2><Icon name="spark"/>Coach 的观察</h2><span className="small-muted">有依据，不下定论</span></div><blockquote>{pending?.summary || state.profile.dimensions.find(d => d.key === state.profile!.focus)?.hypothesis || '还需要更多训练记录才能形成判断。'}</blockquote><p>{pending?.adjustment.reason || '初始画像来自你的自评。记录一次具体动作，能帮助下一次计划更贴近你的状态。'}</p><button className="text-button green" onClick={() => go(pending ? 'report' : 'profile')}>{pending ? '查看反馈与待确认调整' : '查看画像与判断依据'}<Icon name="arrow" size={16}/></button><div className="insight-divider"/><span className="section-label">今天可以问</span><button className="question-link" onClick={() => go('knowledge')}>为什么这样安排训练？<Icon name="chevron" size={16}/></button><button className="question-link" onClick={() => go('knowledge')}>如何记录一次脚点滑落？<Icon name="chevron" size={16}/></button></section></div></> : <><div className="section-head outside"><h2>一个 Coach，一段持续的训练旅程。</h2><span>从今天的状态，到下一次行动</span></div><div className="feature-grid">{[{ n: '01', icon: 'profile', title: '先理解你', text: '区分自评、事实与假设。每条画像都能查看依据、补充或纠正。' }, { n: '02', icon: 'plan', title: '计划适合生活', text: '把目标、时间和场地一起考虑，让每次到馆知道从哪里开始。' }, { n: '03', icon: 'message', title: '反馈改变下一步', text: '结束训练先保存，再轻量复盘。计划调整由你确认，变化可以追溯。' }].map(f => <section className="card feature-card" key={f.n}><div><span className="feature-icon"><Icon name={f.icon} size={23}/></span><span className="feature-number">{f.n}</span></div><h3>{f.title}</h3><p>{f.text}</p></section>)}</div><div className="getting-started"><Icon name="leaf" size={23}/><p>从你能做到的一小步开始。<span>你不需要准确评估所有能力，“暂不清楚”也是有效答案。</span></p><button className="text-button green" onClick={() => go('onboarding')}>开始认识自己<Icon name="arrow" size={16}/></button></div></>}
  </div>;
}

function Onboarding({ state, provider, act, busy, go }: Shared) {
  const [form, setForm] = useState<ProfileInput>(() => state.profile ? { ...state.profile } : (() => { try { return { ...defaultProfile, ...JSON.parse(localStorage.getItem(`climbai.profileDraft.${sessionId()}`) || '{}') }; } catch { return defaultProfile; } })());
  const [adult, setAdult] = useState(!!state.profile?.adult_confirmed); const [error, setError] = useState('');
  useEffect(() => { localStorage.setItem(`climbai.profileDraft.${sessionId()}`, JSON.stringify(form)); }, [form]);
  const change = <K extends keyof ProfileInput>(key: K, value: ProfileInput[K]) => setForm(p => ({ ...p, [key]: value }));
  const submit = async (e: FormEvent) => { e.preventDefault(); setError(''); if (!adult) { setError('当前体验面向 18 岁及以上用户，请确认后继续。'); return; } if (!form.nickname.trim()) { setError('请填写你的称呼。'); return; } if (form.goal.trim().length < 2) { setError('请填写希望持续观察的训练目标。'); return; }
    const willPause = form.recent_pain || state.paused || hasPainSignal(form.goal);
    const saved = await act(() => provider.saveProfile({ ...form, adult_confirmed: adult }), willPause ? '档案已保存，相关训练建议已暂停。' : undefined);
    if (saved) { localStorage.removeItem(`climbai.profileDraft.${sessionId()}`); if (willPause) go('profile'); else await act(() => provider.generatePlan(), '已生成计划草案，请查看并确认。', () => go('plan')); }
  };
  return <form className="onboarding-layout" onSubmit={submit}><div className="form-main"><section className="card form-section"><div className="form-section-title"><span>01</span><div><h2>你的攀爬背景</h2><p>只收集会影响计划的信息。</p></div></div><div className="form-grid"><label>怎么称呼你 <span className="required">*</span><input data-testid="profile-nickname" value={form.nickname} onChange={e => change('nickname', e.target.value)} maxLength={24} placeholder="例如：小林" required/></label><label>攀岩经历<select value={form.experience_months} onChange={e => change('experience_months', Number(e.target.value))}><option value={0}>还没有开始</option><option value={1}>1 个月以内</option><option value={3}>约 1–3 个月</option><option value={6}>约 3–6 个月</option><option value={12}>约 6–12 个月</option><option value={18}>超过一年</option></select></label><label>稳定完成范围<select value={form.grade} onChange={e => change('grade', e.target.value)}><option>暂不清楚</option><option>V0–V1</option><option>V1–V2</option><option>V2–V3</option><option>V3–V4</option><option>V4 以上</option></select><small>同一岩馆的稳定范围，最高等级不用于能力评分。</small></label><label>常去的岩馆<input value={form.gym} onChange={e => change('gym', e.target.value)} maxLength={80} placeholder="可选，便于理解等级场景"/></label></div><fieldset className="equipment-fields"><legend>场地条件</legend><label className="check-label"><input type="checkbox" checked={form.equipment.includes('climbing_wall')} onChange={e => change('equipment', e.target.checked ? [...form.equipment, 'climbing_wall'] : form.equipment.filter(x => x !== 'climbing_wall'))}/>室内抱石墙</label><label className="check-label"><input type="checkbox" checked={form.equipment.includes('mat')} onChange={e => change('equipment', e.target.checked ? [...form.equipment, 'mat'] : form.equipment.filter(x => x !== 'mat'))}/>配有保护垫</label></fieldset></section>
    <section className="card form-section"><div className="form-section-title"><span>02</span><div><h2>把目标放进生活</h2><p>首版用可观察的训练行为作为目标。</p></div></div><label className="field-label">优先关注什么？</label><div className="focus-grid">{(Object.entries(focusLabels) as [Focus, string][]).map(([k, label]) => <button type="button" key={k} className={`focus-choice ${form.focus === k ? 'selected' : ''}`} onClick={() => { change('focus', k); change('goal', `建立每周到馆与复盘习惯，观察${label}相关的动作`); }}><span>{label}</span>{form.focus === k && <Icon name="check" size={17}/>}</button>)}</div><div className="form-grid"><label>每周能到馆几次<select value={form.sessions_per_week} onChange={e => change('sessions_per_week', Number(e.target.value))}><option value={1}>1 次 · 建立节奏</option><option value={2}>2 次 · 练习与复习</option><option value={3}>3 次 · 保留恢复间隔</option></select></label><label>单次可用时间<select value={form.available_minutes} onChange={e => change('available_minutes', Number(e.target.value))}>{[20, 30, 45, 60, 75, 90, 120].map(x => <option value={x} key={x}>{x} 分钟</option>)}</select></label></div><label className="full-field">我的训练目标 <span className="required">*</span><textarea data-testid="profile-goal" value={form.goal} onChange={e => change('goal', e.target.value)} maxLength={240} minLength={2} rows={3} required placeholder="例如：每周到馆两次，记录脚点滑落发生的动作"/><small>这里不会承诺等级提升，也不要求你准确判断自己所有能力。</small></label></section>
    <section className="card form-section"><div className="form-section-title"><span>03</span><div><h2>确认今天的状态</h2><p>不适信息会优先影响计划。</p></div></div><label className="check-label pain-check"><input type="checkbox" checked={form.recent_pain} onChange={e => change('recent_pain', e.target.checked)}/><div><strong>最近出现疼痛或明显不适</strong><small>勾选后保存档案，并暂停相关攀爬建议。系统不判断伤病原因。</small></div></label><label className="check-label adult-check"><input data-testid="profile-adult" type="checkbox" checked={adult} onChange={e => setAdult(e.target.checked)}/>我已年满 18 岁，了解当前内容是产品 Demo 的示例训练条目。</label>{error && <p className="field-error" role="alert">{error}</p>}<button data-testid="profile-save" className="button primary full" disabled={!!busy} type="submit">{form.recent_pain ? '保存档案与状态' : state.profile ? '保存目标，重新生成计划' : '生成我的初始计划'}<Icon name="arrow" size={18}/></button></section></div>
    <aside className="onboarding-aside"><div className="card summary-card"><span className="feature-icon"><Icon name="spark" size={23}/></span><h3>一份了解你的计划</h3><p>你的回答会决定训练安排，而不只是成为聊天背景。</p><div className="summary-row"><span>本周节奏</span><strong>{form.sessions_per_week} 次 × {form.available_minutes} 分钟</strong></div><div className="summary-row"><span>优先重点</span><strong>{focusLabels[form.focus]}</strong></div><div className="summary-row"><span>画像依据</span><strong>初始自评，待验证</strong></div><div className="notice"><Icon name="shield" size={17}/><p>没有测量的力量和耐力会显示“未知”，不会生成看似科学的能力分数。</p></div></div><div className="form-aside-note"><Icon name="leaf" size={21}/><p>不知道从哪里开始也没关系。<br/>先记录一条具体观察。</p></div></aside>
  </form>;
}

function ProfilePage({ state, provider, act, go, busy }: Shared) {
  const [correction, setCorrection] = useState<Dimension | null>(null); const [text, setText] = useState(''); const p = state.profile;
  if (!p) return <Empty title="先建立你的初始画像" text="画像会区分自评、训练事实与待验证判断。没有记录时，我们不会编造结论。" action="建立个人档案" onClick={() => go('onboarding')} icon="profile"/>;
  return <><div className="profile-intro card"><div><span className="avatar large">{p.nickname.slice(0, 1)}</span><div><h2>{p.nickname} 的训练画像</h2><p>稳定范围 {p.grade} · {p.gym || '岩馆未填写'} · {p.experience_months} 个月经历</p></div></div><Pill>画像 v{p.version} · {p.dimensions.some(d => d.evidence_level === '单次记录') ? '已有训练观察' : '基于自评'}</Pill></div><div className="profile-facts"><section className="card"><div className="section-head"><h2><Icon name="check"/>已知事实</h2><span className="small-muted">来自你的填写与记录</span></div><ul className="fact-list">{p.facts.map((x, i) => <li key={i}><span className="small-dot"/>{x}</li>)}</ul></section><section className="card"><div className="section-head"><h2><Icon name="knowledge"/>还不知道的事</h2><Pill tone="neutral">不做推断</Pill></div><ul className="fact-list">{p.missing_fields.map((x, i) => <li key={i}><span className="small-dot muted-dot"/>{x}</li>)}</ul></section></div><div className="section-head outside"><h2>训练维度与观察</h2><span>可以随时纠正</span></div><div className="dimension-grid">{p.dimensions.map((d, i) => <section className="card dimension-card" key={d.key}><div className="section-head"><h3><span className="dimension-number">0{i + 1}</span>{d.label}</h3><Pill tone={d.evidence_level === '资料不足' ? 'neutral' : 'green'}>{d.evidence_level}</Pill></div><div className="dimension-layer"><span>事实观察</span><p>{d.observation}</p></div><div className="dimension-layer hypothesis"><span>待验证判断</span><p>{d.hypothesis}</p></div><div className="dimension-layer"><span>下一步</span><p>{d.next_step}</p></div><div className="dimension-footer"><span><Icon name="link" size={13}/>{d.evidence_ids.length ? `依据：${d.evidence_ids.map(x => x.startsWith('profile-') ? '用户自评 / 纠正' : '训练记录').join('、')}` : '暂无训练证据'}</span><button className="text-button green" onClick={() => { setCorrection(d); setText(d.correction || ''); }}>纠正<Icon name="edit" size={14}/></button></div></section>)}</div><div className="notice"><Icon name="shield"/><p>画像帮助选择下一次观察重点，不能替代专业技术评估。力量、耐力与跨馆等级比较尚无测量依据。</p></div>{correction && <Modal title={`纠正「${correction.label}」`} close={() => setCorrection(null)}><p className="modal-copy">告诉 Coach 哪条理解不准确。你的纠正会保存为新的画像版本，不直接改变已确认计划。</p><label className="full-field">我希望补充<textarea value={text} onChange={e => setText(e.target.value)} rows={4} maxLength={500} placeholder="例如：脚点滑落只出现在某一条困难线路，不是每次训练都有。" autoFocus/></label><div className="modal-actions"><button className="button subtle" onClick={() => setCorrection(null)}>取消</button><button className="button primary" disabled={!!busy || !text.trim()} onClick={() => act(() => provider.correctProfile(correction.key, text), '纠正已保存为新的画像版本。', () => setCorrection(null))}>保存纠正<Icon name="check" size={16}/></button></div></Modal>}</>;
}

function PlanPage({ state, provider, act, go, busy }: Shared) {
  const [expanded, setExpanded] = useState<string | null>(null); const plan = state.current_plan;
  if (!state.profile) return <Empty title="先告诉 Coach 你的目标" text="训练计划会考虑你的时间、场地和当前状态。" action="建立档案与目标" onClick={() => go('onboarding')} icon="plan"/>;
  if (!plan) return <Empty title={state.paused ? '当前先照顾身体状态' : '你的档案已经准备好了'} text={state.paused ? '相关训练建议已暂停，不会在不适状态下生成攀爬任务。' : '基于现有档案生成计划草案，再由你决定是否执行。'} action={state.paused ? '查看并修改档案' : '生成我的一周计划'} onClick={() => state.paused ? go('onboarding') : act(() => provider.generatePlan(), '计划草案已生成。')} icon="plan"/>;
  return <><section className="card plan-overview"><div className="section-head"><div><span className="section-label">PLAN v{plan.version}</span><h2>{plan.title}</h2></div><Pill tone={plan.status === 'confirmed' ? 'green' : 'orange'}>{state.paused ? '已暂停' : plan.status === 'confirmed' ? '已确认' : '草案 · 等待确认'}</Pill></div><p className="large-text">{plan.goal}</p><p className="muted">{plan.summary}</p><div className="plan-overview-bottom"><span><Icon name="clock" size={16}/>{plan.sessions.length} 次到馆 · 单次 {plan.sessions[0]?.duration_minutes || 0} 分钟</span><span><Icon name="profile" size={16}/>关联画像 v{plan.profile_version || state.profile.version}</span><button className="text-button green" onClick={() => go('onboarding')}>修改时间与目标<Icon name="edit" size={14}/></button></div></section>
    <div className="plan-layout"><div className="plan-sessions">{plan.sessions.map((session, index) => { const done = state.logs.some(l => l.session_id === session.id); const open = expanded === session.id || (expanded === null && index === 0); return <section className={`card plan-session ${state.paused ? 'paused-card' : ''}`} key={session.id}><button className="plan-session-head" onClick={() => setExpanded(open ? '' : session.id)} aria-expanded={open}><span className="session-index">{String(index + 1).padStart(2, '0')}</span><div><span className="section-label">{session.day}</span><h3>{session.title}</h3><p>{session.duration_minutes} 分钟 · {session.exercises.length} 个环节</p></div><Pill tone={state.paused ? 'orange' : done ? 'green' : 'neutral'}>{state.paused ? '暂停' : done ? '已记录' : '待训练'}</Pill><Icon name="chevron" size={18} className={open ? 'rotate' : ''}/></button>{open && <div className="plan-session-body"><p className="session-rationale"><Icon name="spark" size={16}/>{session.rationale}</p><ol className="plan-exercises">{session.exercises.map(e => <li key={e.id}><div><strong>{e.title}</strong><span>{e.duration_minutes} min</span></div><p>{e.rationale}</p><ul>{e.steps.map((s, i) => <li key={i}>{s}</li>)}</ul></li>)}</ol><div className="stop-note"><Icon name="shield" size={16}/>{session.stop_condition}</div></div>}</section>; })}</div>
    <aside className="plan-aside"><section className="card"><div className="section-head"><h2><Icon name="spark"/>为什么这样安排</h2></div><p>{plan.rationale}</p><Sources citations={plan.citations}/><div className="notice compact"><p>当前是示例训练模板，上线前需专业人员审阅。计划不保证等级提升。</p></div></section><section className="card confirmation-card"><h3>{plan.status === 'confirmed' ? '计划已由你确认' : '准备好，才开始。'}</h3><p>{plan.status === 'confirmed' ? '执行中可以减少内容或停止，结束训练会独立保存事实。' : '确认表示将这份草案作为当前安排。后续调整仍需要你确认。'}</p><button data-testid="plan-confirm" className="button primary full" disabled={!!busy || state.paused} onClick={() => plan.status === 'confirmed' ? go('training') : act(() => provider.confirmPlan(plan.version), '本周计划已确认。', () => go('training'))}>{plan.status === 'confirmed' ? '进入训练' : '确认本周计划'}<Icon name="arrow" size={16}/></button><button data-testid="plan-generate" className="button subtle full" disabled={!!busy || state.paused} onClick={() => act(() => provider.generatePlan(), '已生成新的计划草案，旧版本仍保留。')}>重新生成草案<Icon name="refresh" size={16}/></button></section></aside></div></>;
}

function TrainingPage(props: Shared) {
  const { state, go } = props; const plan = state.current_plan;
  const [selectedId, setSelectedId] = useState('');
  if (!plan || plan.status !== 'confirmed') return <Empty title={state.paused ? '先暂停，关注今天的状态' : '先确认一份训练计划'} text={state.paused ? '相关攀爬任务已停止推荐；你仍然可以查看原计划与历史记录。' : '查看训练目的、步骤与适用条件，然后确认开始。'} action="查看 AI 周计划" onClick={() => go('plan')} icon="training"/>;
  const selected = plan.sessions.find(s => s.id === selectedId) || plan.sessions.find(s => !state.logs.some(l => l.session_id === s.id)) || plan.sessions[0];
  if (!selected) return <Empty title="当前没有训练任务" text="调整目标与时间，重新生成一份计划。" action="调整目标" onClick={() => go('onboarding')}/>;
  return <><div className="session-tabs">{plan.sessions.map((s, i) => <button data-testid={`training-session-${s.id}`} className={selected.id === s.id ? 'active' : ''} key={s.id} onClick={() => setSelectedId(s.id)}><span>第 {i + 1} 次</span><strong>{s.title}</strong>{state.logs.some(l => l.session_id === s.id) && <Icon name="check" size={16}/>}</button>)}</div><TrainingSession {...props} key={selected.id} sessionId={selected.id} plan={plan}/></>;
}
function TrainingSession({ state, provider, act, go, busy, sessionId: selectedId, plan }: Shared & { sessionId: string; plan: Plan }) {
  const session = plan.sessions.find(s => s.id === selectedId)!;
  const log = state.logs.find(l => l.session_id === selectedId); const report = state.reports.find(r => r.session_id === selectedId);
  const draftKey = `climbai.feedback.${sessionId()}.${selectedId}`;
  const [minutes, setMinutes] = useState(log?.actual_minutes ?? session.duration_minutes);
  const [checks, setChecks] = useState<string[]>([]);
  const [feedback, setFeedback] = useState<FeedbackInput>(() => { try { return { difficulty: 3, completed: true, main_issue: '暂无明显卡点', pain: false, notes: '', ...JSON.parse(localStorage.getItem(draftKey) || '{}') }; } catch { return { difficulty: 3, completed: true, main_issue: '暂无明显卡点', pain: false, notes: '' }; } });
  useEffect(() => { if (!report) localStorage.setItem(draftKey, JSON.stringify(feedback)); }, [feedback, draftKey, report]);
  const change = <K extends keyof FeedbackInput>(k: K, v: FeedbackInput[K]) => setFeedback(x => ({ ...x, [k]: v }));
  return <div className="training-layout"><div><section className="card training-intro"><div className="section-head"><span className="section-label">{session.day} · PLAN v{plan.version}</span><Pill tone={state.paused ? 'orange' : log ? 'green' : 'neutral'}>{state.paused ? '已暂停' : log ? '完成事件已保存' : '训练中'}</Pill></div><h2>{session.title}</h2><p>{session.rationale}</p><div className="inline-info"><Icon name="clock" size={16}/>{session.duration_minutes} 分钟预算 <span>·</span> 可按状态减少内容</div></section><div className="training-exercises">{session.exercises.map((e, i) => <section className={`card exercise-card ${checks.includes(e.id) ? 'checked' : ''}`} key={e.id}><div className="exercise-head"><span className="exercise-number">0{i + 1}</span><div><h3>{e.title}</h3><span>{e.duration_minutes} 分钟 · {e.rationale}</span></div><button className={`check-button ${checks.includes(e.id) ? 'checked' : ''}`} disabled={state.paused || !!log} aria-label={`${checks.includes(e.id) ? '取消' : '标记'}完成 ${e.title}`} onClick={() => setChecks(x => x.includes(e.id) ? x.filter(id => id !== e.id) : [...x, e.id])}><Icon name="check" size={17}/></button></div><ol>{e.steps.map((x, n) => <li key={n}>{x}</li>)}</ol><button className="text-button green" onClick={() => go('knowledge')}>为什么这样做？<Icon name="knowledge" size={14}/></button></section>)}</div><div className="stop-note"><Icon name="shield" size={18}/>{session.stop_condition}</div></div>
    <aside className="training-aside"><section className="card"><div className="section-head"><h2><Icon name="training"/>训练记录</h2></div>{log ? <div className="saved-event"><span className="saved-check"><Icon name="check" size={22}/></span><h3>完成事件已保存</h3><p>{fmtDate(log.completed_at)} · {log.actual_minutes} 分钟</p><small>即使稍后提交反馈，这条训练事实也会保留。</small></div> : <><p className="muted">先记录结束时间，再决定是否补充反馈。</p><label className="full-field">实际训练时长<div className="input-unit"><input data-testid="training-minutes" type="number" min={0} max={240} step={1} value={minutes} onChange={e => setMinutes(Number(e.target.value))} aria-label="实际训练时长"/><span>分钟</span></div></label><small className="small-muted">0 分钟表示本次跳过。完成标记只是本页清单。</small><button data-testid="training-complete" className="button primary full" disabled={!!busy || state.paused} onClick={() => act(() => provider.completeSession(selectedId, minutes), '完成事件已独立保存，反馈可以稍后补充。')}>结束训练，保存记录<Icon name="check" size={17}/></button></>}
      {report ? <div className="feedback-done"><Pill>反馈已提交</Pill><p>{report.summary}</p><button className="button primary full" onClick={() => go('report')}>查看反馈报告<Icon name="arrow" size={16}/></button></div> : log ? <div className="feedback-form"><div className="form-divider"/><h3>用一分钟，留下观察。</h3><p className="small-muted">草稿自动保存在此浏览器，可稍后继续。</p><label className="full-field">完成情况<select value={feedback.completed ? 'yes' : 'no'} onChange={e => change('completed', e.target.value === 'yes')}><option value="yes">完成主要内容</option><option value="no">部分完成 / 跳过</option></select></label><fieldset className="difficulty"><legend>主观难度</legend><div>{[1, 2, 3, 4, 5].map(n => <button data-testid={`feedback-difficulty-${n}`} type="button" key={n} className={feedback.difficulty === n ? 'active' : ''} onClick={() => change('difficulty', n)}>{n}</button>)}</div><span>1 轻松 <span>5 很吃力</span></span></fieldset><label className="full-field">主要卡点<select data-testid="feedback-issue" value={feedback.main_issue} onChange={e => change('main_issue', e.target.value)}>{['暂无明显卡点', '脚点滑落', '读线与动作选择', '身体平衡', '时间不足', '状态与疲劳', '其他'].map(x => <option key={x}>{x}</option>)}</select></label><label className="full-field">补充一句话 <span className="optional">可选</span><textarea data-testid="feedback-notes" rows={3} value={feedback.notes} onChange={e => change('notes', e.target.value)} maxLength={1000} placeholder="例如：滑落只出现在困难线路，容易线路没有问题。"/></label><label className="check-label pain-check"><input data-testid="feedback-pain" type="checkbox" checked={feedback.pain} onChange={e => change('pain', e.target.checked)}/><div><strong>训练中出现疼痛或明显不适</strong><small>提交后立即暂停相关任务。</small></div></label><button data-testid="feedback-submit" className="button primary full" disabled={!!busy} onClick={() => act(() => provider.feedback(selectedId, feedback), feedback.pain ? '已暂停相关任务，并生成状态说明。' : '反馈已提交，查看下一次建议。', () => { localStorage.removeItem(draftKey); go('report'); })}>{feedback.pain ? '记录不适，暂停相关训练' : '提交反馈，查看调整'}<Icon name="arrow" size={16}/></button><button className="text-button later" onClick={() => go('today')}>稍后反馈，返回今日</button></div> : <div className="feedback-placeholder"><Icon name="message" size={24}/><p>保存训练完成事件后，<br/>这里会出现轻量反馈。</p></div>}</section></aside></div>;
}

function ReportPage({ state, provider, act, go, busy }: Shared) {
  const [selected, setSelected] = useState('');
  const report = state.reports.find(r => r.id === selected) || state.reports[state.reports.length - 1];
  if (!report) return <Empty title="还没有训练反馈报告" text="结束一次训练并提交反馈，Coach 才能根据真实记录提出下一步建议。" action="前往训练记录" onClick={() => go('training')} icon="report"/>;
  const pending = report.adjustment.status === 'pending'; const stale = (state.current_plan?.version ?? 0) !== report.adjustment.base_plan_version || (report.adjustment.profile_version !== undefined && report.adjustment.profile_version !== state.profile?.version);
  return <>{state.reports.length > 1 && <div className="report-picker"><label>查看历史报告<select value={report.id} onChange={e => setSelected(e.target.value)}>{[...state.reports].reverse().map((r, i) => <option value={r.id} key={r.id}>{fmtDate(r.created_at)} · {r.summary || `报告 ${i + 1}`}</option>)}</select></label></div>}
    <section className="report-hero card"><span className="report-hero-icon"><Icon name="spark" size={30}/></span><div><div className="section-label">COACH REFLECTION · {fmtDate(report.created_at)}</div><h2>{report.summary}</h2><p>{report.adjustment.reason}</p></div><Pill tone={pending ? 'orange' : 'green'}>{pending ? '等待确认' : report.adjustment.status === 'kept' ? '已保持原计划' : '已确认下一步'}</Pill></section><div className="report-grid"><section className="card"><div className="section-head"><h2><Icon name="check"/>这次发生了什么</h2><span className="small-muted">来自训练记录</span></div><ul className="observation-list">{report.observations.map((o, i) => <li key={i}><span>0{i + 1}</span><p>{o}</p></li>)}</ul></section><section className="card"><div className="section-head"><h2><Icon name="knowledge"/>如何理解这次经历</h2><Pill tone="neutral">待验证</Pill></div>{report.hypotheses.map((h, i) => <p key={i} className="hypothesis-text">{h}</p>)}<div className="notice compact"><p>一次成功不自动增加强度，一次未完成也不直接判定能力下降。</p></div></section></div>
    <section className="card adjustment-card"><div className="section-head"><h2><Icon name="plan"/>下一次，怎样安排</h2><span className="small-muted">基于计划 v{report.adjustment.base_plan_version}</span></div><div className="comparison"><div><span className="section-label">原计划</span><p>{report.before || '保持当前已确认训练安排'}</p></div><span className="comparison-arrow"><Icon name="arrow" size={23}/></span><div className="suggested"><span className="section-label">建议下一步</span><p>{report.after || report.adjustment.changes.join('；')}</p></div></div><p className="adjustment-reason"><Icon name="spark" size={17}/>{report.adjustment.reason}</p>{pending && stale ? <div className="notice warning"><Icon name="alert"/><p>当前计划或画像已经更新。这份旧报告只能查看，不能覆盖新的安排。</p></div> : pending ? <div className="adjustment-actions"><button data-testid="adjustment-accept" className="button primary" disabled={!!busy} onClick={() => act(() => provider.decide(report.id, 'accept', report.adjustment.base_plan_version), '已确认下一次安排，历史版本已保留。')}>{state.paused ? '确认已暂停，先关注状态' : report.adjustment.proposed_plan ? '接受调整' : '确认保持当前安排'}<Icon name="check" size={17}/></button>{!state.paused && report.adjustment.proposed_plan && <button data-testid="adjustment-keep" className="button subtle" disabled={!!busy} onClick={() => act(() => provider.decide(report.id, 'keep', report.adjustment.base_plan_version), '已保持原计划，并保存你的选择。')}>保持原计划</button>}<button className="text-button green" onClick={() => go('onboarding')}>调整目标与时间<Icon name="edit" size={14}/></button></div> : <div className="confirmed-notice"><Icon name="check" size={19}/>你的选择已经保存。<button className="text-button green" onClick={() => go('plan')}>查看当前计划<Icon name="arrow" size={15}/></button></div>}</section><Sources citations={report.citations}/><div className="report-links"><button className="text-button green" onClick={() => go('profile')}>查看更新后的能力画像<Icon name="arrow" size={16}/></button><button className="text-button green" onClick={() => go('account')}>查看计划与训练历史<Icon name="history" size={16}/></button></div></>;
}

function KnowledgePage({ state, provider, busy, toast, setState }: Shared & { setState: (state: AppState | ((previous: AppState) => AppState)) => void }) {
  const [question, setQuestion] = useState(''); const [asking, setAsking] = useState(false); const [latest, setLatest] = useState<Answer | null>(null);
  const answer = latest || state.answers[state.answers.length - 1];
  const metadata = state.knowledge_meta || knowledgeMetadata;
  const ask = async (q: string) => { if (!q.trim() || asking || busy) return; setAsking(true); setQuestion(q); try { const result = { ...await provider.ask(q), question: q }; setLatest(result); const next = await provider.getState(); if (!next.answers.some(a => a.run_id && a.run_id === result.run_id)) next.answers.push(result); setState(next); } catch (e) { toast(e instanceof Error ? e.message : '问答失败，请重试。', true); } finally { setAsking(false); } };
  return <div className="knowledge-layout"><section className="knowledge-main"><div className="card knowledge-welcome"><span className="feature-icon"><Icon name="knowledge" size={26}/></span><h2>把“为什么”，问清楚。</h2><p>从 {metadata.knowledge_count} 条知识中查找技术观察、装备、岩馆规则与训练记录的依据。先选一个问题，也可以描述自己的攀岩场景；未命中来源时会说明不足。</p><div className="quick-questions">{knowledgeQuestions.map(q => <button onClick={() => ask(q)} disabled={asking || !!busy} key={q}>{q}<Icon name="arrow" size={14}/></button>)}</div></div>
    {answer && <><div className="user-question"><span className="avatar">{state.profile?.nickname.slice(0, 1) || '你'}</span><p>{answer.question || '你之前的问题'}</p></div><section className="card answer-card"><div className="section-head"><h2><Icon name="spark"/>Coach 的解释</h2><Pill tone={answer.insufficient_evidence ? 'orange' : 'green'}>{answer.insufficient_evidence ? '资料不足 / 超出范围' : '依据已列出'}</Pill></div><p className="answer-text">{answer.answer}</p><Sources citations={answer.citations}/><span className="answer-engine">{answer.provider === 'demo' || answer.provider === 'demo_rules' || /rule/i.test(answer.provider) ? '示例规则回答 · 未调用模型' : `回答引擎：${answer.provider}`}</span></section></>}
    {asking && <div className="card answer-loading" role="status"><span className="spinner"/>正在检查问题范围与检索依据…</div>}
    <form className="question-form card" onSubmit={e => { e.preventDefault(); void ask(question); }}><label htmlFor="knowledge-question" className="sr-only">输入攀岩训练问题</label><textarea data-testid="knowledge-question" id="knowledge-question" rows={2} value={question} onChange={e => setQuestion(e.target.value)} maxLength={1000} placeholder="例如：踩小脚点时不稳，踩边和摩擦有什么区别？"/><button data-testid="knowledge-submit" className="button primary" type="submit" disabled={asking || !!busy || !question.trim()}><Icon name="arrow" size={19}/><span>提问</span></button><small>支持常用中英文攀岩术语；只整理已匹配条目的摘要，不提供伤病诊断或库外处方。</small></form>
  </section><aside className="knowledge-aside"><section className="card"><span className="section-label">知识范围与来源</span><h3>知道依据，也知道边界</h3><div className="summary-row"><span>知识条目</span><strong data-testid="knowledge-count">{metadata.knowledge_count} 条</strong></div>{metadata.reference_page_count !== undefined && <div className="summary-row"><span>参考页面</span><strong>{metadata.reference_page_count} 个</strong></div>}<p>包含参考资料的中文简要摘要，以及明确标注的 ClimbAI 产品规则。每条回答可查看引用与适用范围。</p><div className="notice compact"><p>{metadata.review_status}。来源核验不等于专业教练审核，也不代表训练效果已经验证。</p></div></section><section className="card"><span className="section-label">与你有关的上下文</span><h3>{state.profile ? focusLabels[state.profile.focus] : '尚未建立档案'}</h3><p>{state.profile?.goal || '无需建档也能查基础知识；建立档案后可查看自己的训练重点与时间预算。'}</p><div className="summary-row"><span>计划版本</span><strong>{state.current_plan ? `v${state.current_plan.version}` : '暂无'}</strong></div><div className="summary-row"><span>已记录训练</span><strong>{state.logs.length} 次</strong></div><div className="notice compact"><p>不会凭借聊天推断未测量的能力，也不会把模拟案例当成真实进步。</p></div></section>{state.answers.length > 0 && <section className="card question-history"><div className="section-head"><h3>最近问过</h3><Icon name="history" size={16}/></div>{[...state.answers].reverse().slice(0, 5).map((a, i) => <button key={a.id || i} onClick={() => { setLatest(a); setQuestion(a.question || ''); }}>{a.question || '历史问答'}<Icon name="chevron" size={14}/></button>)}</section>}</aside></div>;
}

function AccountPage({ state, provider, act, go, busy, toast, mode }: Shared) {
  const [tab, setTab] = useState<'logs' | 'plans' | 'profiles' | 'runs'>('logs'); const [deleting, setDeleting] = useState(false);
  const exportData = async () => { try { const data = await provider.exportData(); const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `ClimbAI-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); URL.revokeObjectURL(url); toast('训练数据已导出。'); } catch (e) { toast(e instanceof Error ? e.message : '导出失败', true); } };
  return <><section className="card account-summary"><span className="avatar large">{state.profile?.nickname.slice(0, 1) || '你'}</span><div><h2>{state.profile?.nickname || '你的个人训练空间'}</h2><p>{state.profile?.goal || '从一个可观察的目标开始，留下训练足迹。'}</p><span className="small-muted">{mode === 'demo' ? '数据保存在此浏览器 · 不会上传到服务端' : '匿名会话数据存储于已连接后端'}</span></div><button className="button subtle" onClick={() => go('onboarding')}><Icon name="edit" size={16}/>{state.profile ? '修改档案' : '建立档案'}</button></section><div className="account-shortcuts"><button className="card" onClick={() => go('profile')}><Icon name="profile"/><div><strong>能力画像</strong><small>事实与可纠正判断</small></div><Icon name="chevron" size={17}/></button><button className="card" onClick={() => go('report')}><Icon name="report"/><div><strong>反馈报告</strong><small>调整理由与选择</small></div><Icon name="chevron" size={17}/></button></div>
    <section className="card history-card"><div className="history-tabs" role="tablist" aria-label="历史记录">{[{ key: 'logs', label: '训练事实', count: state.logs.length }, { key: 'plans', label: '计划版本', count: state.plans.length }, { key: 'profiles', label: '画像版本', count: state.profile_versions.length }, { key: 'runs', label: 'Coach 过程', count: state.runs.length }].map(t => <button role="tab" aria-selected={tab === t.key} className={tab === t.key ? 'active' : ''} onClick={() => setTab(t.key as typeof tab)} key={t.key}>{t.label}<span>{t.count}</span></button>)}</div><div className="history-content">
    {tab === 'logs' && (state.logs.length ? [...state.logs].reverse().map(l => { const oldPlan = state.plans.find(p => p.id === l.plan_id && (l.plan_version === undefined || p.version === l.plan_version)); const oldSession = oldPlan?.sessions.find(s => s.id === l.session_id); return <div className="history-row" key={l.id}><span className="history-row-icon"><Icon name="training"/></span><div><strong>{oldSession?.title || '一次训练记录'}</strong><p>{fmtDate(l.completed_at)} · 实际 {l.actual_minutes} 分钟 · 计划 v{l.plan_version || oldPlan?.version || '?'}</p></div><Pill tone={l.sample ? 'orange' : l.feedback_submitted || state.reports.some(r => r.session_id === l.session_id) ? 'green' : 'neutral'}>{l.sample ? '模拟记录' : l.feedback_submitted || state.reports.some(r => r.session_id === l.session_id) ? '已反馈' : '待补反馈'}</Pill></div>; }) : <Empty title="还没有训练事实" text="结束训练时会独立保存记录，尚未反馈的训练也会显示。" icon="training"/>)}
    {tab === 'plans' && (state.plans.length ? [...state.plans].reverse().map(p => <details className="history-detail" key={`${p.id}:${p.version}`}><summary><span className="version-badge">v{p.version}</span><div><strong>{p.title}</strong><p>{fmtDate(p.created_at)} · {p.sessions.length} 次训练 · {p.status === 'paused' ? '已暂停' : p.status === 'confirmed' ? '已确认' : '草案'}</p></div>{p.id === state.current_plan_id && p.version === state.current_plan?.version && <Pill>当前版本</Pill>}<Icon name="chevron" size={17}/></summary><div className="history-detail-body"><p>{p.goal}</p><p>{p.rationale}</p>{p.sessions.map(s => <div className="history-plan-session" key={s.id}><strong>{s.day} · {s.title}</strong><span>{s.duration_minutes} 分钟</span></div>)}</div></details>) : <Empty title="还没有计划版本" text="生成与确认计划后，历史版本都会保留。" icon="plan"/>)}
    {tab === 'profiles' && (state.profile_versions.length ? [...state.profile_versions].reverse().map(p => <details className="history-detail" key={p.version}><summary><span className="version-badge">v{p.version}</span><div><strong>{p.nickname} 的训练画像</strong><p>{fmtDate(p.created_at)} · {focusLabels[p.focus]}</p></div><Icon name="chevron" size={17}/></summary><div className="history-detail-body">{p.dimensions.map(d => <p key={d.key}><strong>{d.label}：</strong>{d.observation}<span className="small-muted"> · {d.evidence_level}</span></p>)}</div></details>) : <Empty title="还没有画像版本" text="建档、补充反馈和纠正画像都会留下快照。" icon="profile"/>)}
    {tab === 'runs' && (state.runs.length ? [...state.runs].reverse().map(r => <details className="history-detail" key={r.id}><summary><span className="history-row-icon"><Icon name="spark"/></span><div><strong>{r.workflow || 'Coach 工作流'}</strong><p>{fmtDate(r.created_at)} · {r.provider || state.engine} · {r.status}</p></div><Icon name="chevron" size={17}/></summary><div className="history-detail-body"><div className="run-steps">{(r.nodes || []).map((n, i) => <span key={i}><Icon name="check" size={13}/>{typeof n === 'string' ? n : n.node}</span>)}</div><p className="small-muted">{r.model_calls === 0 ? '示例规则执行，无模型调用。' : r.model_calls !== undefined ? `模型调用 ${r.model_calls} 次。` : '实际执行记录由服务端提供。'}{r.duration_ms !== undefined ? ` 耗时 ${r.duration_ms} ms。` : ''}</p></div></details>) : <Empty title="还没有 Coach 过程记录" text="生成计划、提交反馈和知识问答后，可查看受控工作流。" icon="spark"/>)}
    </div></section><section className="card data-card"><div><h3>我的数据，由我管理。</h3><p>导出档案、原始训练事实、画像与计划版本。删除只影响当前{mode === 'demo' ? '浏览器演示空间' : '匿名 API 会话'}。</p></div><div><button data-testid="data-export" className="button subtle" onClick={exportData} disabled={!!busy}><Icon name="download" size={17}/>导出 JSON</button><button data-testid="data-clear" className="button danger-outline" onClick={() => setDeleting(true)} disabled={!!busy}><Icon name="trash" size={16}/>删除我的数据</button></div></section>{deleting && <Modal title="删除当前训练空间" close={() => setDeleting(false)}><p className="modal-copy">此操作会清除当前{mode === 'demo' ? '浏览器演示空间' : '匿名会话'}的档案、记录、报告和版本。建议先导出需要保留的内容。</p><div className="modal-actions"><button className="button subtle" onClick={() => setDeleting(false)}>取消</button><button className="button danger" disabled={!!busy} onClick={() => act(() => provider.clearData(), '当前训练数据已删除。', () => { for (let i = localStorage.length - 1; i >= 0; i--) { const key = localStorage.key(i); if (key?.startsWith(`climbai.feedback.${sessionId()}.`) || key === `climbai.profileDraft.${sessionId()}`) localStorage.removeItem(key); } setDeleting(false); go('today'); })}>确认删除</button></div></Modal>}</>;
}

function ConnectionModal({ mode, apiUrl, configurationWarning, close, apply }: { mode: ProviderMode; apiUrl: string; configurationWarning?: string; close: () => void; apply: (mode: ProviderMode, url: string) => Promise<void> }) {
  const [selected, setSelected] = useState(mode); const [url, setUrl] = useState(apiUrl); const [error, setError] = useState(''); const [connecting, setConnecting] = useState(false);
  const submit = async () => { setError(''); if (selected === 'api') { try { const parsed = new URL(url.trim()); if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password || parsed.search || parsed.hash) throw new Error(); } catch { setError('请输入有效的 http / https 后端地址，不包含账号、密码或查询参数。'); return; } } setConnecting(true); try { await apply(selected, url.trim().replace(/\/$/, '')); } finally { setConnecting(false); } };
  return <Modal title="选择体验模式" close={close}><div className="connection-options" data-testid="mode-select"><button className={selected === 'demo' ? 'selected' : ''} onClick={() => setSelected('demo')}><Icon name="mountain"/><div><strong>本地演示模式</strong><p>无需后端 · 示例规则 · 浏览器保存</p></div>{selected === 'demo' && <Icon name="check" size={18}/>}</button><button className={selected === 'api' ? 'selected' : ''} onClick={() => setSelected('api')}><Icon name="link"/><div><strong>连接 Coach API</strong><p>独立后端 · 匿名会话 · 服务端模型配置</p></div>{selected === 'api' && <Icon name="check" size={18}/>}</button></div>{selected === 'api' && <><label className="full-field">后端服务地址<input data-testid="api-url" value={url} onChange={e => setUrl(e.target.value)} placeholder="http://127.0.0.1:8000"/><small>仅填写已部署的 FastAPI 地址。模型密钥只在后端设置。</small></label><div className="notice compact"><p>网页与 API 需配置相应跨域访问。公开网页建议连接 HTTPS 服务；浏览器可能限制对本地服务的访问。</p></div></>}{configurationWarning && mode === 'api' && <div className="notice warning"><Icon name="alert"/><p>{configurationWarning}</p></div>}<p className="small-muted">两个模式的数据相互独立。切换模式不会把本地模拟记录上传到 API。</p>{error && <p className="field-error" role="alert">{error}</p>}<div className="modal-actions"><button className="button subtle" onClick={close}>取消</button><button data-testid="mode-apply" className="button primary" disabled={connecting} onClick={submit}>{connecting ? '正在检查…' : selected === 'api' ? '检查并连接' : '使用演示模式'}<Icon name="arrow" size={16}/></button></div></Modal>;
}
